import{_ as o,a0 as r,w as a,s as u,ao as s,I as e,x as i,a1 as p,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"精通Linux的“kill”命令 | LCTT x X-CMD","titleTemplate":false,"description":"精通Linux的“kill”命令 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"精通Linux的“kill”命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"精通Linux的“kill”命令 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Mastering the “Kill” Command in Linux","title":"精通Linux的“kill”命令","tag":"201310","desc":""},"relativePath":"201310/Mastering the “Kill” Command in Linux.md","filePath":"[post].md"}'),d={name:"201310/Mastering the “Kill” Command in Linux.md"};function m(k,l,x,f,L,T){const t=r("Link");return a(),u("div",null,[l[14]||(l[14]=s(`<h1 id="精通linux的-kill-命令" tabindex="-1">精通Linux的“kill”命令 <a class="header-anchor" href="#精通linux的-kill-命令" aria-label="Permalink to “精通Linux的“kill”命令”">​</a></h1><p>无论你使用哪种操作系统，你一定会遇到某个行为失常的应用，它把自己锁死并拒绝关闭。在Linux(还有Mac)，你可以用一个&quot;kill&quot;命令强制终结它。在这个教程中，我们将展示给你多种方式使用&quot;kill&quot;命令终结应用。</p><p>###Kill命令和信号</p><p>当你执行一个&quot;kill&quot;命令，你实际上发送了一个信号给系统，让它去终结不正常的应用。总共有60个你可以使用的信号，但是基本上你只需要知道SIGTERM(15)和SIGKILL(9)。</p><p>你可以用这个命令看到所有信号的列表：</p><pre><code>kill -l
</code></pre><p><img src="http://i1.wp.com/imagecdn5.maketecheasier.com/2013/10/kill-list-signal.png" alt=""></p><ul><li>SIGTERM - 此信号请求一个进程停止运行。此信号是可以被忽略的。进程可以用一段时间来正常关闭，一个程序的正常关闭一般需要一段时间来保存进度并释放资源。换句话说，它不是强制停止。</li><li>SIGKILL - 此信号强制进程立刻停止运行。程序不能忽略此信号，而未保存的进度将会丢失。</li></ul><p>使用&quot;kill&quot;的语法是：</p><pre><code>kill [信号或选项] PID(s)
</code></pre><p>默认信号（当没有指定的时候）是SIGTERM。当它不起作用时，你可以使用下面的命令来强制kill掉一个进程:</p><pre><code>kill SIGKILL PID
</code></pre><p>或者</p><pre><code>kill -9 PID
</code></pre><p>这里&quot;-9&quot;代表着SIGKILL信号。</p><p>如果你不知道应用的PID，仅需要运行这个命令：</p><pre><code>ps ux
</code></pre><p>它会显示所有正在运行的应用还有应用的PID。</p><p><img src="http://i1.wp.com/imagecdn5.maketecheasier.com/2013/10/kill-find-pid.png" alt=""></p><p>例如，要kill掉Chrome，我会运行命令：</p><pre><code>kill -9 3629
</code></pre><p>也可以在同一时间kill多个进程。</p><pre><code>kill -9 PID1 PID2 PID3
</code></pre><p>###PKill</p><p>&quot;pkill&quot;命令允许使用扩展的正则表达式和其它匹配方式。你现在可以使用应用的进程名kill掉它们，而不是使用PID。例如，要kill掉Firefox浏览器，只需要运行命令：</p><pre><code>pkill firefox
</code></pre><p>使用正则表达式匹配的话，你可以输入进程名的部分字符，比如：</p><pre><code>pkill fire
</code></pre><p>为了避免kill掉错误的进程，你应该用一下&quot;pgrep -l [进程名]&quot;列表来匹配进程名称。</p><p><img src="http://i0.wp.com/imagecdn5.maketecheasier.com/2013/10/kill-pgrep-command.png" alt=""></p><p>###Killall</p><p>killall同样使用进程名替代PID，并且它会kill掉所有的同名进程。例如，如果你正在运行多个Firefox浏览器的实例，可以用命令把它们全部kill掉:</p><pre><code>killall firefox
</code></pre><p>在Gnome中，你可以使用这个命令重启Nautilus：</p><pre><code>killall nautilus
</code></pre><p>###xkill</p>`,36)),e("p",null,[l[1]||(l[1]=i('xkill 是图形方式kill一个应用。当你在终端键入"xkill"，你的光标将立刻变成一个"十字"。你只需要做的是在不正常的应用上点击一下，它就会立刻kill掉这个应用。如果你经常用的话，你也可以添加一个',-1)),p(t,{href:"http://www.maketecheasier.com/quick-tips/kill-unresponsive-application-in-ubuntu/"},{default:n(()=>[...l[0]||(l[0]=[i("键盘快捷键来激活xkill",-1)])]),_:1}),l[2]||(l[2]=i("。",-1))]),l[15]||(l[15]=e("p",null,"###结论",-1)),l[16]||(l[16]=e("p",null,'当应用不正常而导致系统挂起的时候，人们往往重启计算机并且再一次开启所有的任务。而有了这些"kill"命令，你将能够更好的处理不正常的应用，从而避免导致系统崩溃。当你不想因一个不正常的进程而导致服务器宕机时，它尤其的有用。',-1)),l[17]||(l[17]=e("hr",null,null,-1)),e("p",null,[l[4]||(l[4]=i("via: ",-1)),p(t,{href:"http://www.maketecheasier.com/kill-command-in-linux/"},{default:n(()=>[...l[3]||(l[3]=[i("http://www.maketecheasier.com/kill-command-in-linux/",-1)])]),_:1})]),e("p",null,[l[7]||(l[7]=i("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...l[5]||(l[5]=[i("LCTT",-1)])]),_:1}),l[8]||(l[8]=i(" 原创翻译，",-1)),p(t,{href:"http://linux.cn/"},{default:n(()=>[...l[6]||(l[6]=[i("Linux中国",-1)])]),_:1}),l[9]||(l[9]=i(" 荣誉推出",-1))]),e("p",null,[l[12]||(l[12]=i("译者：",-1)),p(t,{href:"https://github.com/flsf"},{default:n(()=>[...l[10]||(l[10]=[i("flsf",-1)])]),_:1}),l[13]||(l[13]=i(" 校对：",-1)),p(t,{href:"https://github.com/wxy"},{default:n(()=>[...l[11]||(l[11]=[i("wxy",-1)])]),_:1})])])}const P=o(d,[["render",m]]);export{C as __pageData,P as default};
